class Directory:
    """Everyone we know about, without duplicates."""

    def __init__(self):
        self._customers = {}

    def add(self, customer):
        """Registers the customer; returns False if that person was already known."""
        if customer in self._customers:
            return False
        self._customers[customer] = customer
        return True

    def find(self, email):
        from customer import Customer

        return self._customers.get(Customer(email))

    def __len__(self):
        return len(self._customers)

