class Mailer:
    """Sends one message per person, however many lists they are on."""

    def __init__(self):
        self.sent = []

    def send_to_all(self, *lists, subject=""):
        recipients = set()
        for customers in lists:
            recipients.update(customers)
        for customer in sorted(recipients, key=lambda c: c.email.lower()):
            self.sent.append((customer.email, subject))
        return len(recipients)

